P = [
 dict(pmid='43065452', doi='10.1038/s44407-026-00116-y', journal='NPJ Clean Air', title='Variability and controls of wildfire smoke infiltration in school buildings.', tier='A', basis='Low-cost sensor / network', short='Five New York K-12 schools, paired calibrated indoor/outdoor sensors: wildfire-day indoor PM2.5 10.09 vs 3.71 ug/m3 (2.72-fold); infiltration factor 0.69-0.95', design='Multi-site monitoring campaign', pm='Hourly paired indoor and outdoor PM2.5 from calibrated sensors; satellite smoke and network PM2.5 to classify regimes; mass-balance infiltration factor Finf', geo='USA (New York Capital Region)', endpoint='Indoor PM2.5 and infiltration factor of outdoor wildfire PM2.5 in school buildings', n='Paired indoor-outdoor PM2.5 from calibrated sensors at five K-12 schools in New York\'s Capital Region, September 2024 to December 2025; satellite smoke plus network PM2.5 classified regimes, and emission screening with a mass balance isolated outdoor-derived particles to estimate Finf. Mean indoor PM2.5 was 10.09 ug/m3 on wildfire days vs 3.71 on other days (2.72-fold), driven by outdoor PM2.5; Finf stayed high (0.69-0.95 across schools) and slightly above clean-background values (0.65-0.92). Outside smoke, Finf rose with outdoor temperature to a plateau near 20-25 C (0.77-0.78) and was higher on school days and in instructional hours. Weakness: five schools in one region, no CIs, and sensor calibration details and smoke-specific optical bias are not given in the abstract. Relevance: a direct template for school sensor networks - paired indoor/outdoor low-cost units yield building-specific Finf during smoke.', sub=corpus.OCC),
 dict(pmid='', doi='10.21203/rs.3.rs-11793536/v1', journal='Research Square', title='Quantifying Spatial Cross-Validation Inflation in Satellite-Ground Air Quality Coupling: Mesoscale NDVI/LST Regimes and Land Use Regression Across an Urban Megacity', tier='B', basis='Satellite-fused', short='Kolkata-Howrah, 13 regulatory stations: random 10-fold CV R2 0.84 vs spatial-block/LOSO R2 0.58 for PM2.5 (1.45x inflation)', design='Spatial cross-validation, operational network', pm='Station PM2.5 and PM10 (13 regulatory monitors, 2024-2025) modelled from Landsat-8/9 NDVI, NDBI and LST in 500-5000 m buffers (LUR)', geo='India (Kolkata-Howrah)', endpoint='Out-of-sample R2 of satellite-ground LUR under random vs spatial cross-validation', n='Preprint, not peer reviewed. Land use regression of PM2.5 and PM10 at 13 regulatory stations in the Kolkata-Howrah conurbation (2024-2025) on 30 m Landsat-8/9 NDVI, NDBI and land surface temperature over 500-5000 m buffers. Random 10-fold cross-validation gave R2 0.84 for PM2.5; spatial block and leave-one-station-out validation gave 0.58, an inflation factor of 1.45. Dense vegetation (NDVI > 0.45) was associated with up to 24.3% lower PM2.5 than built-up surfaces (NDBI > 0.15); thermal and built-up drivers dominated at 500-1000 m, green space at 2000-5000 m. Weakness: 13 stations is too few for a stable LUR or a credible LOSO estimate, no uncertainty on R2, and the vegetation effect is cross-sectional. Relevance: quantifies why dense sensor networks matter - with 13 sites, honest spatial validation removes a third of apparent skill.', sub=corpus.EXPO),
 dict(pmid='', doi='10.21203/rs.3.rs-11793674/v1', journal='Research Square', title='Topological Data Analysis of Urban Air Quality Monitoring Networks: Vietoris-Rips Simplicial Filtration, Persistent Homology, and Geostatistical Connectivity in a Bifurcated Riverine Airshed', tier='C', basis='Reference / regulatory monitor', short='Persistent homology of 13 Hooghly-conurbation stations: network consolidates at 14.5 km; PM Moran I falls from +1.017 at 2 km to random by 7 km', design='Spatial analysis / GIS', pm='Station PM2.5, PM10 and NO2 from 13 regulatory monitors used to ground graph and topological filtrations', geo='India (Kolkata-Howrah, Hooghly River)', endpoint='Network geometry: persistent homology invariants, Moran I and semivariogram range', n='Preprint, not peer reviewed; same author and 13-station Kolkata-Howrah network as the companion LUR preprint. Vietoris-Rips filtration and classical graphs (Delaunay, Gabriel, MST) describe network geometry: zero-dimensional homology shows hierarchical percolation with consolidation at 14.50 km, and the only one-dimensional cycle (trans-river) is shown to be a coordinate-discretisation artefact. Grounded in PM2.5, PM10 and NO2 data, Moran I moves from localised clustering (+1.017 at 2 km) to random expectation (-0.083) at 7 km, consistent with a 5.29 km semivariogram practical range. Weakness: a mathematical description of 13 points; no test of whether the topology improves interpolation or siting, and no uncertainty on Moran I. Relevance: the ~5-7 km decorrelation scale is a usable spacing target for densifying the network with low-cost sensors.', sub=corpus.SENS),
]
